  const supplyIp = Math.random() < 0.5;
  const ip:
    | (string & (tags.Format<"ipv4"> | tags.Format<"ipv6">))
    | null
    | undefined = supplyIp
    ? typia.random<string & tags.Format<"ipv4">>()
    : undefined;
  const joinRequest = {
    email,
    password,
    href,
    referrer,
    ip,
