import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test that a newly registered user can create a todo item and then retrieve
 * its details using the todo's UUID.
 *
 * Steps:
 *
 * 1. Register a user (join) to get an authenticated session
 * 2. Create a todo with both required and optional fields (title, description,
 *    due_date)
 * 3. Retrieve the todo using its id
 * 4. Assert all returned fields are accurate, match the original creation, and
 *    belong to the authenticated user
 * 5. Confirm no other user can access this todo (isolation guaranteed)
 */
export async function test_api_user_todo_detail_retrieval(
  connection: api.IConnection,
) {
  // 1. Register a new user for authentication
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<
      string & tags.MinLength<8> & tags.MaxLength<72> & tags.Format<"password">
    >(),
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
    ip: null,
  } satisfies ITodoAppUser.IJoin;
  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: userJoinBody },
  );
  typia.assert(user);
  TestValidator.equals(
    "registered user email matches input",
    user.email,
    userJoinBody.email,
  );
  TestValidator.predicate(
    "token is issued for new user",
    typeof user.token.access === "string" && user.token.access.length > 0,
  );

  // 2. Create a todo with all fields
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 10 }),
    description: RandomGenerator.paragraph({
      sentences: 6,
      wordMin: 4,
      wordMax: 12,
    }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // 1 day from now
  } satisfies ITodoAppTodo.ICreate;
  const created: ITodoAppTodo = await api.functional.todoApp.user.todos.create(
    connection,
    { body: todoCreateBody },
  );
  typia.assert(created);
  TestValidator.equals(
    "created todo title matches input",
    created.title,
    todoCreateBody.title,
  );
  TestValidator.equals(
    "created todo description matches input",
    created.description,
    todoCreateBody.description,
  );
  TestValidator.equals(
    "created todo due_date matches input",
    created.due_date,
    todoCreateBody.due_date,
  );
  TestValidator.equals(
    "status is 'active' on creation",
    created.status,
    "active",
  );
  TestValidator.equals(
    "created todo is owned by the newly registered user",
    created.todo_app_user_id,
    user.id,
  );

  // 3. Retrieve the todo details by id
  const fetched: ITodoAppTodo = await api.functional.todoApp.user.todos.at(
    connection,
    { todoId: created.id },
  );
  typia.assert(fetched);
  TestValidator.equals(
    "fetched todo id matches created",
    fetched.id,
    created.id,
  );
  TestValidator.equals(
    "fetched title matches created",
    fetched.title,
    created.title,
  );
  TestValidator.equals(
    "fetched description matches created",
    fetched.description,
    created.description,
  );
  TestValidator.equals(
    "fetched due_date matches created",
    fetched.due_date,
    created.due_date,
  );
  TestValidator.equals(
    "fetched todo status matches created",
    fetched.status,
    created.status,
  );
  TestValidator.equals(
    "fetched and created timestamps match",
    fetched.created_at,
    created.created_at,
  );
  TestValidator.equals(
    "fetched updated_at matches created",
    fetched.updated_at,
    created.updated_at,
  );
  TestValidator.equals(
    "fetched todo is owned by authenticated user",
    fetched.todo_app_user_id,
    user.id,
  );

  // 4. Permission: Create another user and ensure that user cannot access the first user's todo
  const otherUserBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<
      string & tags.MinLength<8> & tags.MaxLength<72> & tags.Format<"password">
    >(),
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
    ip: null,
  } satisfies ITodoAppUser.IJoin;
  const otherUser: ITodoAppUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: otherUserBody });
  typia.assert(otherUser);
  TestValidator.notEquals(
    "other user should have a distinct uuid",
    otherUser.id,
    user.id,
  );
  await TestValidator.error(
    "other user cannot access first user's todo",
    async () => {
      await api.functional.todoApp.user.todos.at(connection, {
        todoId: created.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * E2E test verifying that an admin can retrieve the details of any user's todo
 * item.
 *
 * This test walks through the following steps:
 *
 * 1. Registers an admin and a normal user account to create independent
 *    authentication contexts.
 * 2. Logs in as the new user and creates a todo item with random title,
 *    description, and due_date.
 * 3. Logs in as the admin and fetches the created todo item by its unique id.
 * 4. Validates:
 *
 *    - The admin can access the todo details.
 *    - All business fields (title, status, due_date, description, audit fields) are
 *         present and valid.
 *    - The owner id matches the user who created the todo.
 *    - The status is "active", and permission boundary is respected (admin can get
 *         any todo).
 */
export async function test_api_admin_todo_detail_retrieval(
  connection: api.IConnection,
) {
  // Generate unique test data credentials
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const userEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const userPassword = RandomGenerator.alphaNumeric(12);

  // 1. Register admin and user
  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin-portal.example.com/register",
      referrer: "https://admin-portal.example.com/login",
    } satisfies ITodoAppAdmin.IJoin,
  });
  typia.assert(adminAuth);

  const userAuth = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: "https://app.example.com/register",
      referrer: "https://app.example.com/login",
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(userAuth);

  // 2. Login as user and create todo
  await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    } satisfies ITodoAppUser.ILogin,
  });

  const todoCreateInput = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // tomorrow
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo = await api.functional.todoApp.user.todos.create(
    connection,
    {
      body: todoCreateInput,
    },
  );
  typia.assert(createdTodo);
  TestValidator.equals(
    "todo title matches input",
    createdTodo.title,
    todoCreateInput.title,
  );
  TestValidator.equals(
    "todo description matches input",
    createdTodo.description,
    todoCreateInput.description,
  );
  TestValidator.equals(
    "todo due_date matches input",
    createdTodo.due_date,
    todoCreateInput.due_date,
  );
  TestValidator.equals(
    "todo status is 'active' immediately after creation",
    createdTodo.status,
    "active",
  );

  // 3. Login as admin
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin-portal.example.com/login",
      referrer: "https://admin-portal.example.com/home",
    } satisfies ITodoAppAdmin.ILogin,
  });

  // 4. Admin fetches the todo details by todoId
  const fetchedTodo = await api.functional.todoApp.admin.todos.at(connection, {
    todoId: createdTodo.id,
  });
  typia.assert(fetchedTodo);
  TestValidator.equals(
    "fetched todo id matches created todo",
    fetchedTodo.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "fetched todo owner matches user who created it",
    fetchedTodo.todo_app_user_id,
    userAuth.id,
  );
  TestValidator.equals(
    "fetched todo title matches input",
    fetchedTodo.title,
    todoCreateInput.title,
  );
  TestValidator.equals(
    "fetched todo description matches input",
    fetchedTodo.description,
    todoCreateInput.description,
  );
  TestValidator.equals(
    "fetched todo due_date matches input",
    fetchedTodo.due_date,
    todoCreateInput.due_date,
  );
  TestValidator.equals(
    "fetched todo status is active",
    fetchedTodo.status,
    "active",
  );
  TestValidator.predicate(
    "admin has access to another user's todo",
    fetchedTodo.todo_app_user_id !== adminAuth.id,
  );
  // Audit fields validation
  TestValidator.predicate(
    "created_at must be ISO string",
    typeof fetchedTodo.created_at === "string" &&
      !isNaN(Date.parse(fetchedTodo.created_at)),
  );
  TestValidator.predicate(
    "updated_at must be ISO string",
    typeof fetchedTodo.updated_at === "string" &&
      !isNaN(Date.parse(fetchedTodo.updated_at)),
  );
  TestValidator.equals(
    "completed_at is null/undefined for active todo",
    fetchedTodo.completed_at,
    null,
  );
  TestValidator.equals(
    "deleted_at is null/undefined for active todo",
    fetchedTodo.deleted_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test refreshing JWT tokens for a user with a valid refresh token.
 *
 * Validates the /auth/user/refresh endpoint by simulating the scenario where an
 * existing user has a non-expired refresh token (issued during successful
 * login/join) and submits it for renewal. Successful response must include new
 * tokens in the response and return correct session information (user id,
 * email, created_at, updated_at, deleted_at, token block). The test checks that
 * the structure of issued tokens is valid, and their expiration times are in
 * the future.
 *
 * Steps:
 *
 * 1. Generate a fake authorized user session (simulates join or login).
 * 2. Request token refresh using the previously issued refresh token from the
 *    authorized session.
 * 3. Assert that a new authorized session is returned with valid fields, and
 *    returned token information is updated.
 * 4. Assert that user identity (id, email) is preserved, but the access and
 *    refresh tokens have changed.
 * 5. Optionally, check that expired_at and refreshable_until in token are proper
 *    valid ISO date-times in the future.
 */
export async function test_api_user_token_refresh_valid(
  connection: api.IConnection,
) {
  // 1. Simulate generating an authorized session (join/login)
  const authorized: ITodoAppUser.IAuthorized =
    typia.random<ITodoAppUser.IAuthorized>();
  typia.assert(authorized); // Just in case

  // 2. Request token refresh using the authorized's refresh token
  const refreshed: ITodoAppUser.IAuthorized =
    await api.functional.auth.user.refresh(connection, {
      body: {
        refresh_token: authorized.token.refresh,
      } satisfies ITodoAppUser.IRefresh,
    });
  typia.assert(refreshed);

  // 3. Assert core identity (id/email) stays the same
  TestValidator.equals(
    "id should not change after refresh",
    refreshed.id,
    authorized.id,
  );
  TestValidator.equals(
    "email should not change after refresh",
    refreshed.email,
    authorized.email,
  );

  // 4. Assert that token information is present and properly updated
  typia.assert<IAuthorizationToken>(refreshed.token);
  TestValidator.notEquals(
    "access token must be newly issued (should differ)",
    refreshed.token.access,
    authorized.token.access,
  );
  TestValidator.notEquals(
    "refresh token must be newly issued (should differ)",
    refreshed.token.refresh,
    authorized.token.refresh,
  );

  // 5. Assert that expiration fields are valid ISO date-times and in the future (relative to now)
  const now = Date.now();
  const accessExpiry = Date.parse(refreshed.token.expired_at);
  const refreshExpiry = Date.parse(refreshed.token.refreshable_until);
  TestValidator.predicate(
    "token.expired_at is in the future",
    accessExpiry > now,
  );
  TestValidator.predicate(
    "token.refreshable_until is in the future",
    refreshExpiry > now,
  );

  // 6. 'deleted_at' must be null or undefined for an active user
  TestValidator.equals(
    "deleted_at should be null or undefined for active user",
    refreshed.deleted_at ?? null,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Tests token refresh attempt with an invalid or tampered refresh token.
 *
 * Ensures the API correctly rejects requests with invalid, malformed, or
 * expired tokens, returning proper error responses and not issuing new tokens
 * or session data.
 *
 * 1. Try to refresh token with a random string as refresh token (not a JWT)
 * 2. Try to refresh token with a string that superficially resembles a JWT but is
 *    not valid/issued
 * 3. Try to refresh token with an empty string (totally malformed)
 * 4. For each case, verify that the API returns an error, does not issue session
 *    data, and does not leak info
 */
export async function test_api_user_token_refresh_invalid_token(
  connection: api.IConnection,
) {
  // 1. Completely random string (not JWT)
  await TestValidator.error(
    "refresh fails with completely random string",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: RandomGenerator.alphaNumeric(40),
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // 2. Well-formed but fake JWT-like string
  await TestValidator.error(
    "refresh fails with plausible but non-issued JWT-like string",
    async () => {
      // Structure: header.payload.signature, all base64-ish
      const fakeJwt = [
        RandomGenerator.alphaNumeric(24),
        RandomGenerator.alphaNumeric(36),
        RandomGenerator.alphaNumeric(44),
      ].join(".");
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: fakeJwt,
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );

  // 3. Empty string
  await TestValidator.error(
    "refresh fails with an empty string token",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: "",
        } satisfies ITodoAppUser.IRefresh,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Tests refresh token attempt for a user account that has been soft-deleted.
 * Ensures a refresh token associated with a deleted user cannot be used to
 * generate new authentication tokens, validating correct account status
 * enforcement in the refresh workflow.
 */
export async function test_api_user_token_refresh_deleted_user(
  connection: api.IConnection,
) {
  // Step 1: Prepare a deleted user's refresh token (mock approach, since we cannot create or delete users in this scope)
  // Simulate a refresh token referencing a user with a non-null deleted_at, which should be rejected by the server.
  // This token cannot be generated via public API, so use random string for the refresh_token value.
  const refreshRequest = {
    refresh_token: RandomGenerator.alphaNumeric(64),
  } satisfies ITodoAppUser.IRefresh;

  // Step 2: Attempt refresh and expect error
  await TestValidator.error(
    "cannot refresh token for soft-deleted user",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: refreshRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";

/**
 * Validates successful registration of a new administrator using valid, unique
 * email and password, along with session context fields (href, referrer,
 * optional ip).
 *
 * This test ensures:
 *
 * 1. A new administrator can register using a unique email and a plaintext
 *    password in compliance with business/password policy.
 * 2. Session context (href and referrer URIs, plus optional ip) is supplied for
 *    audit and compliance tracking.
 * 3. Upon success, the admin record is created, password is returned as a hash
 *    (not plaintext), tokens and session details are returned.
 * 4. All returned data adheres to security, business, and audit expectations.
 */
export async function test_api_admin_registration_success(
  connection: api.IConnection,
) {
  // Generate a unique email for the new admin
  const email = typia.random<string & tags.Format<"email">>();
  // Generate a strong, random password
  const password = RandomGenerator.alphaNumeric(12);
  // Supply valid absolute URLs for session context
  const href = "https://admin.todoapp.io/registration";
  const referrer = "https://todoapp.io/home";
  // Optionally include an IP address (cover optional/undefined/null)
  const ip = typia.random<string & tags.Format<"ipv4">>();

  // Prepare join request body (all required session/audit context fields)
  const joinBody = {
    email,
    password,
    ip, // test presence of optional IP (could omit to test defaulting)
    href,
    referrer,
  } satisfies ITodoAppAdmin.IJoin;

  // Register the administrator
  const result = await api.functional.auth.admin.join(connection, {
    body: joinBody,
  });
  typia.assert(result);

  // Validate all required fields and security policies in response
  TestValidator.equals("registered email matches request", result.email, email);
  // Password returned should be password_hash (NOT the plaintext password!)
  TestValidator.predicate(
    "password is returned as a hash, not plaintext",
    typeof result.password_hash === "string" &&
      !result.password_hash.includes(password) &&
      result.password_hash.length >= 32,
  );
  // Confirm UUID, timestamp, tokens, etc.
  TestValidator.predicate(
    "id is UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
      result.id,
    ),
  );
  TestValidator.predicate(
    "admin created_at is date-time",
    /T.*Z$/.test(result.created_at),
  );
  TestValidator.predicate(
    "admin updated_at is date-time",
    /T.*Z$/.test(result.updated_at),
  );
  TestValidator.predicate(
    "token is present",
    !!result.token && !!result.token.access && !!result.token.refresh,
  );
  TestValidator.predicate(
    "token.expired_at and refreshable_until are date-time",
    /T.*Z$/.test(result.token.expired_at) &&
      /T.*Z$/.test(result.token.refreshable_until),
  );
  // Session must exist and have correct context data
  TestValidator.predicate("admin session summary present", !!result.session);
  if (result.session) {
    TestValidator.equals(
      "session admin_id matches returned id",
      result.session.admin_id,
      result.id,
    );
    TestValidator.equals("session ip matches input", result.session.ip, ip);
    TestValidator.equals(
      "session href matches input",
      result.session.href,
      href,
    );
    TestValidator.equals(
      "session referrer matches input",
      result.session.referrer,
      referrer,
    );
    TestValidator.predicate(
      "session id is UUID",
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
        result.session.id,
      ),
    );
    TestValidator.predicate(
      "session created_at is date-time",
      /T.*Z$/.test(result.session.created_at),
    );
  }
  TestValidator.equals(
    "deleted_at is null for active admin",
    result.deleted_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";

/**
 * Validates that admin registration correctly rejects attempts to use an
 * already-registered email. Ensures that business privacy and security policies
 * are upheld by not leaking whether a specific admin exists.
 *
 * 1. Register a new admin using a unique random email and password
 * 2. Attempt registering another admin using the same email but a different
 *    password
 * 3. Expect the second attempt to fail (error thrown)
 * 4. The error must be generic: no indication should be given whether the email
 *    existed previously
 */
export async function test_api_admin_registration_duplicate_email(
  connection: api.IConnection,
) {
  // 1. Register a new admin with a unique email
  const uniqueEmail = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const registrationBody = {
    email: uniqueEmail,
    password: password,
    href: "https://example.com/register",
    referrer: "https://example.com/referrer",
  } satisfies ITodoAppAdmin.IJoin;

  const joinResult = await api.functional.auth.admin.join(connection, {
    body: registrationBody,
  });
  typia.assert(joinResult);
  TestValidator.equals(
    "registered email matches",
    joinResult.email,
    uniqueEmail,
  );
  TestValidator.equals(
    "no deletion timestamp on first registration",
    joinResult.deleted_at,
    null,
  );

  // 2. Attempt to register a second admin with the same email but different password+href+referrer
  const secondBody = {
    email: uniqueEmail,
    password: RandomGenerator.alphaNumeric(16),
    href: "https://example.com/register2",
    referrer: "https://example.com/referrer2",
  } satisfies ITodoAppAdmin.IJoin;

  await TestValidator.error(
    "duplicate admin registration is rejected without info leak",
    async () => {
      await api.functional.auth.admin.join(connection, {
        body: secondBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import type { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";

/**
 * Attempts administrator registration using a password that violates the
 * password policy, expecting failure.
 *
