        : todo.description === null
          ? null
          : todo.description,
    status: typia.assert<"active" | "deleted" | "completed">(todo.status),
    due_date:
      typeof todo.due_date === "undefined"
        ? undefined
        : todo.due_date === null
          ? null
          : toISOStringSafe(todo.due_date),
    created_at: toISOStringSafe(todo.created_at),
    updated_at: toISOStringSafe(todo.updated_at),
    completed_at:
      typeof todo.completed_at === "undefined"
        ? undefined
        : todo.completed_at === null
          ? null
          : toISOStringSafe(todo.completed_at),
    deleted_at:
      typeof todo.deleted_at === "undefined"
        ? undefined
        : todo.deleted_at === null
          ? null
          : toISOStringSafe(todo.deleted_at),
    todo_app_user_id: todo.todo_app_user_id,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { IPageITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdmin";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminAdmins(props: {
  admin: AdminPayload;
  body: ITodoAppAdmin.IRequest;
}): Promise<IPageITodoAppAdmin.ISummary> {
  const defaultLimit = 100;
  const defaultPage = 1;
  const allowedOrderFields = ["created_at", "email"] as const;
  const allowedSort = ["asc", "desc"] as const;

  const page = props.body.page ?? defaultPage;
  const limit = props.body.limit ?? defaultLimit;
  const order_by: "created_at" | "email" = allowedOrderFields.includes(
    (props.body.order_by ?? "") as "created_at" | "email",
  )
    ? (props.body.order_by as "created_at" | "email")
    : "created_at";
  const sort: "asc" | "desc" = allowedSort.includes(
    (props.body.sort ?? "") as "asc" | "desc",
  )
    ? (props.body.sort as "asc" | "desc")
    : "desc";

  const where = {
    deleted_at: null as null,
    ...(props.body.email ? { email: { contains: props.body.email } } : {}),
    ...(props.body.created_at
      ? { created_at: { gte: props.body.created_at } }
      : {}),
  };

  const [data, total] = await Promise.all([
    MyGlobal.prisma.todo_app_admins.findMany({
      where,
      skip: (page - 1) * limit,
      take: limit,
      orderBy: { [order_by]: sort },
    }),
    MyGlobal.prisma.todo_app_admins.count({ where }),
  ]);

  const admins: ITodoAppAdmin.ISummary[] = data.map((admin) => ({
    id: admin.id,
    email: admin.email,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
  }));

  return {
    data: admins,
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminTodos(props: {
  admin: AdminPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const {
    title,
    description,
    status,
    due_date_from,
    due_date_to,
    created_at_from,
    created_at_to,
    owner_user_id,
    sort_by,
    sort_order,
    page = 1,
    page_size = 20,
  } = props.body || {};

  const take = Math.min(page_size ?? 20, 200);
  const skip = ((page ?? 1) - 1) * take;

  // Build where condition
  const where = {
    ...(title
      ? {
          title: {
            contains: title satisfies string as string,
            mode: "insensitive" as Prisma.QueryMode,
          },
        }
      : {}),
    ...(description
      ? {
          description: {
            contains: description satisfies string as string,
            mode: "insensitive" as Prisma.QueryMode,
          },
        }
      : {}),
    ...(status ? { status } : {}),
    ...(due_date_from || due_date_to
      ? {
          due_date: {
            ...(due_date_from ? { gte: due_date_from } : {}),
            ...(due_date_to ? { lte: due_date_to } : {}),
          },
        }
      : {}),
    ...(created_at_from || created_at_to
      ? {
          created_at: {
            ...(created_at_from ? { gte: created_at_from } : {}),
            ...(created_at_to ? { lte: created_at_to } : {}),
          },
        }
      : {}),
    ...(owner_user_id ? { owner_user_id } : {}),
    deleted_at: null,
  };

  // Supported sort fields
  const sortableFields = [
    "title",
    "created_at",
    "updated_at",
    "due_date",
    "status",
  ];
  const orderByField = sortableFields.includes(sort_by ?? "")
    ? (sort_by as string)
    : "created_at";
  const orderByOrder = sort_order === "asc" ? "asc" : "desc";
  const orderBy: Record<string, "asc" | "desc"> = {
    [orderByField]: orderByOrder,
  };

  // Query todos and count in parallel
  const [todos, records] = await Promise.all([
    MyGlobal.prisma.todo_app_todos.findMany({
      where,
      skip,
      take,
      orderBy,
    }),
    MyGlobal.prisma.todo_app_todos.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: take,
      records,
      pages: Math.ceil(records / take),
    },
    data: todos.map((todo) => ({
      id: todo.id,
      title: todo.title,
      status: todo.status,
      due_date: todo.due_date ? toISOStringSafe(todo.due_date) : null,
      completed_at:
        typeof todo.completed_at === "undefined" || todo.completed_at === null
          ? null
          : toISOStringSafe(todo.completed_at),
      deleted_at:
        typeof todo.deleted_at === "undefined" || todo.deleted_at === null
          ? null
          : toISOStringSafe(todo.deleted_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserSession";
import { IPageITodoAppUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppUserSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminUsersUserIdSessions(props: {
  admin: AdminPayload;
  userId: string & tags.Format<"uuid">;
  body: ITodoAppUserSession.IRequest;
}): Promise<IPageITodoAppUserSession.ISummary> {
  // Step 1: Ensure user exists (privacy requirement)
  const user = await MyGlobal.prisma.todo_app_users.findUnique({
    where: { id: props.userId },
  });
  if (!user || user.deleted_at !== null) {
    throw new HttpException("User not found", 404);
  }

  // Step 2: Build filters
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Build sorting order
  const orderBy =
    props.body.sort &&
    (props.body.sort === "created_at" || props.body.sort === "expired_at")
      ? {
          [props.body.sort]: (props.body.order === "asc"
            ? "asc"
            : "desc") as Prisma.SortOrder,
        }
      : { created_at: "desc" as Prisma.SortOrder };

  // Build where clause
  const where = {
    user_id: props.userId,
    ...(props.body.ip && { ip: props.body.ip }),
    ...(props.body.referrer && { referrer: props.body.referrer }),
    // Date range filter
    ...((props.body.created_from || props.body.created_to) && {
      created_at: {
        ...(props.body.created_from && { gte: props.body.created_from }),
        ...(props.body.created_to && { lte: props.body.created_to }),
      },
    }),
    // Expired filter: true => only expired sessions, false => only active, undefined/null => both
    ...(props.body.expired === true
      ? { expired_at: { not: null } }
      : props.body.expired === false
        ? { expired_at: null }
        : {}),
  };

  // Step 3: Query and count in parallel
  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.todo_app_user_sessions.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_app_user_sessions.count({
      where,
    }),
  ]);

  // Step 4: Map DB records to DTO
  const data = sessions.map((session) => ({
    id: session.id,
    user_id: session.user_id,
    ip: session.ip,
    href: session.href,
    referrer: session.referrer,
    created_at: toISOStringSafe(session.created_at),
    expired_at:
      typeof session.expired_at === "object" && session.expired_at
        ? toISOStringSafe(session.expired_at)
        : session.expired_at === null
          ? null
          : undefined, // careful handling for optional+nullable
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ITodoAppAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminSession";

export async function postAuthAdminJoin(props: {
  body: ITodoAppAdmin.IJoin;
}): Promise<ITodoAppAdmin.IAuthorized> {
  // 1. Check for duplicate admin email
  const existing = await MyGlobal.prisma.todo_app_admins.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered as admin", 409);
  }

  // 2. Hash password
  const password_hash = await PasswordUtil.hash(props.body.password);

  // 3. Prepare timestamps and IDs
  const now: string = toISOStringSafe(new Date());
  const id: string = v4();
  const session_id: string = v4();
  const accessExpiredAt: string = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiredAt: string = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // 4. Insert admin
  const admin = await MyGlobal.prisma.todo_app_admins.create({
    data: {
      id,
      email: props.body.email,
      password_hash,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // 5. Create session
  const ipValue =
    props.body.ip === undefined || props.body.ip === null ? "" : props.body.ip;
  const session = await MyGlobal.prisma.todo_app_admin_sessions.create({
    data: {
      id: session_id,
      admin_id: admin.id,
      ip: ipValue,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpiredAt,
    },
  });

  // 6. Build session DTO summary
  const sessionSummary = {
    id: session.id,
    admin_id: session.admin_id,
    ip: session.ip,
    href: session.href,
    referrer: session.referrer,
    created_at: toISOStringSafe(session.created_at),
  };

  // 7. Generate tokens
  const token = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpiredAt,
    refreshable_until: refreshExpiredAt,
  };

  // 8. Return authorized admin DTO
  return {
    id: admin.id,
    email: admin.email,
    password_hash: admin.password_hash,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    deleted_at:
      admin.deleted_at === null ? undefined : toISOStringSafe(admin.deleted_at),
    token,
    session: sessionSummary,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoAppUserTodos(props: {
  user: UserPayload;
  body: ITodoAppTodo.ICreate;
}): Promise<ITodoAppTodo> {
  // Enforce uniqueness of the title among current user's active todos
  const existing = await MyGlobal.prisma.todo_app_todos.findFirst({
    where: {
      todo_app_user_id: props.user.id,
      title: props.body.title,
      status: "active",
    },
  });
  if (existing) {
    throw new HttpException(
      "You already have an active todo with this title.",
      409,
    );
  }

  // Validate optional due_date: it must be a valid ISO string in the future if provided
  let dueDate: string | null | undefined =
    typeof props.body.due_date === "string" ? props.body.due_date : undefined;
  if (dueDate !== undefined && dueDate !== null) {
    const parsed = Date.parse(dueDate);
    if (isNaN(parsed)) {
      throw new HttpException(
        "due_date must be a valid ISO8601 datetime string.",
        400,
      );
    }
    // Now must be strictly less than dueDate
    if (parsed <= Date.now()) {
      throw new HttpException("due_date must be in the future.", 400);
    }
  }

  // Generate now as an ISO string
  const now = toISOStringSafe(new Date());

  const created = await MyGlobal.prisma.todo_app_todos.create({
    data: {
      id: v4(),
      title: props.body.title,
      description: Object.prototype.hasOwnProperty.call(
        props.body,
        "description",
      )
        ? props.body.description
        : undefined,
      status: "active",
      due_date: dueDate ?? null,
      created_at: now,
      updated_at: now,
      completed_at: null,
      deleted_at: null,
      todo_app_user_id: props.user.id,
    },
  });

  return {
    id: created.id,
    title: created.title,
    description: Object.prototype.hasOwnProperty.call(created, "description")
      ? created.description
      : undefined,
    status: typia.assert<"active" | "completed" | "deleted">(created.status),
    due_date:
      created.due_date != null ? toISOStringSafe(created.due_date) : undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    completed_at:
      created.completed_at != null
        ? toISOStringSafe(created.completed_at)
        : undefined,
    deleted_at:
      created.deleted_at != null
        ? toISOStringSafe(created.deleted_at)
        : undefined,
    todo_app_user_id: created.todo_app_user_id,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoAppUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoAppTodo.IUpdate;
}): Promise<ITodoAppTodo> {
  const todo = await MyGlobal.prisma.todo_app_todos.findUnique({
    where: { id: props.todoId },
  });

  if (
    !todo ||
    todo.todo_app_user_id !== props.user.id ||
    todo.status === "deleted"
  ) {
    throw new HttpException("Todo not found or no permission", 404);
  }

  if (props.body.title !== undefined) {
    const exists = await MyGlobal.prisma.todo_app_todos.findFirst({
      where: {
        id: { not: props.todoId },
        todo_app_user_id: props.user.id,
        status: { not: "deleted" },
        title: props.body.title,
      },
    });
    if (exists) {
      throw new HttpException("A todo with that title already exists.", 409);
    }
  }

  let completed_at = todo.completed_at;
  let deleted_at = todo.deleted_at;
  let status =
    typeof props.body.status !== "undefined" ? props.body.status : todo.status;

  const now = toISOStringSafe(new Date());

  if (props.body.status === "completed" && todo.status !== "completed") {
    completed_at = new Date();
    status = "completed";
  } else if (props.body.status === "deleted" && todo.status !== "deleted") {
    deleted_at = new Date();
    status = "deleted";
  } else if (props.body.status === "active") {
    status = "active";
    completed_at = null;
    deleted_at = null;
  }

  const updated = await MyGlobal.prisma.todo_app_todos.update({
    where: { id: props.todoId },
    data: {
      ...(props.body.title !== undefined ? { title: props.body.title } : {}),
      ...(props.body.description !== undefined
        ? { description: props.body.description }
        : {}),
      ...(props.body.due_date !== undefined
        ? { due_date: props.body.due_date }
        : {}),
      status,
      completed_at,
      deleted_at,
      updated_at: new Date(),
    },
  });

  return {
    id: updated.id,
    title: updated.title,
    description: updated.description ?? undefined,
    status: typia.assert<"active" | "deleted" | "completed">(updated.status),
    due_date:
      updated.due_date === null || updated.due_date === undefined
        ? undefined
        : toISOStringSafe(updated.due_date),
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    completed_at:
      updated.completed_at === null || updated.completed_at === undefined
        ? undefined
        : toISOStringSafe(updated.completed_at),
    deleted_at:
      updated.deleted_at === null || updated.deleted_at === undefined
        ? undefined
        : toISOStringSafe(updated.deleted_at),
    todo_app_user_id: updated.todo_app_user_id,
  };
}

