import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserTodos(props: {
  user: UserPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const {
    title,
    description,
    status,
    due_date_from,
    due_date_to,
    created_at_from,
    created_at_to,
    sort_by,
    sort_order,
    page = 1,
    page_size = 20,
    // owner_user_id is ignored for normal users (cannot override their own id)
  } = props.body;

  // Calculate pagination
  const pageNumber = page ?? 1;
  const limit = page_size ?? 20;
  const skip = (pageNumber - 1) * limit;

  // Only allow sort_by on whitelisted fields
  const sortable: Record<string, true> = {
    title: true,
    created_at: true,
    updated_at: true,
    due_date: true,
    status: true,
  };
  const resolvedSortBy = sort_by && sortable[sort_by] ? sort_by : "created_at";
  const resolvedSortOrder = sort_order === "asc" ? "asc" : "desc";

  // Build search conditions
  const where: Record<string, unknown> = {
    todo_app_user_id: props.user.id,
    ...(status && { status }),
    ...(title && {
      title: {
        contains: title,
        mode: "insensitive",
      },
    }),
    ...(description && {
      description: {
        contains: description,
        mode: "insensitive",
      },
    }),
    ...(due_date_from || due_date_to
      ? {
          due_date: {
            ...(due_date_from && { gte: due_date_from }),
            ...(due_date_to && { lte: due_date_to }),
          },
        }
      : {}),
    ...(created_at_from || created_at_to
      ? {
          created_at: {
            ...(created_at_from && { gte: created_at_from }),
            ...(created_at_to && { lte: created_at_to }),
          },
        }
      : {}),
  };

  // Query database (findMany handles skip/take/orderBy, then count)
  const [todos, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todos.findMany({
      where,
      skip,
      take: limit,
      orderBy: { [resolvedSortBy]: resolvedSortOrder },
      select: {
        id: true,
        title: true,
        status: true,
        due_date: true,
        completed_at: true,
        deleted_at: true,
      },
    }),
    MyGlobal.prisma.todo_app_todos.count({ where }),
  ]);

  // Map DB records to ISummary DTO
  const data: ITodoAppTodo.ISummary[] = todos.map((row) => ({
    id: row.id,
    title: row.title,
    status: row.status,
    due_date: row.due_date == null ? null : toISOStringSafe(row.due_date),
    completed_at:
      row.completed_at == null ? null : toISOStringSafe(row.completed_at),
    deleted_at: row.deleted_at == null ? null : toISOStringSafe(row.deleted_at),
  }));

  return {
    pagination: {
      current: Number(pageNumber),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoAppUser.IJoin;
}): Promise<ITodoAppUser.IAuthorized> {
  // Check for duplicate email
  const existing = await MyGlobal.prisma.todo_app_users.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // Hash password and create user record
  const password_hash = await PasswordUtil.hash(props.body.password);
  const now = toISOStringSafe(new Date());
  const user_id = v4();
  const user = await MyGlobal.prisma.todo_app_users.create({
    data: {
      id: user_id,
      email: props.body.email,
      password_hash,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Create session record with correct 'ip' value
  const session_id = v4();
  const access_expires = new Date(Date.now() + 60 * 60 * 1000);
  const refresh_expires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const ip: string =
    props.body.ip !== null && props.body.ip !== undefined
      ? (props.body.ip satisfies string as string)
      : "";
  const session = await MyGlobal.prisma.todo_app_user_sessions.create({
    data: {
      id: session_id,
      user_id: user.id,
      ip,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: toISOStringSafe(access_expires),
    },
  });

  // Prepare JWT token payload and generate tokens
  const payload = {
    type: "user",
    id: user.id,
    session_id: session.id,
    created_at: now,
  };
  const token: IAuthorizationToken = {
    access: jwt.sign(payload, MyGlobal.env.JWT_SECRET_KEY, {
      expiresIn: "1h",
      issuer: "autobe",
    }),
    refresh: jwt.sign(
      { ...payload, tokenType: "refresh" },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(access_expires),
    refreshable_until: toISOStringSafe(refresh_expires),
  };

  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at === null || typeof user.deleted_at === "undefined"
        ? undefined
        : toISOStringSafe(user.deleted_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoAppUser.IRefresh;
}): Promise<ITodoAppUser.IAuthorized> {
  let decoded: { id: string; session_id: string; type: "user" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "user" };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }
  const sessionWithUser =
    await MyGlobal.prisma.todo_app_user_sessions.findFirst({
      where: {
        id: decoded.session_id,
        user_id: decoded.id,
      },
      include: {
        user: true,
      },
    });
  if (!sessionWithUser) {
    throw new HttpException("Session expired or revoked", 401);
  }
  if (sessionWithUser.user.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }
  const now = Date.now();
  const accessExpires = now + 60 * 60 * 1000; // 1 hour
  const refreshExpires = now + 7 * 24 * 60 * 60 * 1000; // 7 days
  const accessToken = jwt.sign(
    {
      type: "user",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: toISOStringSafe(new Date(now)),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refreshToken = jwt.sign(
    {
      type: "user",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date(now)),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );
  await MyGlobal.prisma.todo_app_user_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: new Date(refreshExpires) },
  });
  const user = sessionWithUser.user;
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at !== null ? toISOStringSafe(user.deleted_at) : undefined,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(new Date(accessExpires)),
      refreshable_until: toISOStringSafe(new Date(refreshExpires)),
    },
  };
}

